class Solution:
    def maxContainers(self, n: int, w: int, maxWeight: int) -> int:
        # Total number of cells available
        total_cells = n * n

        # Maximum number of containers that can be loaded based on weight capacity
        max_by_weight = maxWeight // w

        # The answer is the minimum of the total cells available and the maximum allowed by weight
        return min(total_cells, max_by_weight)
