class Solution:
    def totalNumbers(self, digits: List[int]) -> int:
        from collections import Counter
        count = Counter(digits)
        distinct = set()

        # Generate all possible 3-digit numbers using the available digits
        # We need to consider each digit position: hundreds, tens, units
        # For each combination, we check if the digits are available (respecting counts)

        # Get unique digits to avoid redundant checks
        unique_digits = list(set(digits))

        for h in unique_digits:
            if h == 0:
                continue  # no leading zero
            for t in unique_digits:
                for u in unique_digits:
                    # Check if the number is even
                    if u % 2 != 0:
                        continue
                    # Check if we have enough digits to form h, t, u
                    # Count how many times each digit is needed
                    needed = Counter([h, t, u])
                    valid = True
                    for d, cnt in needed.items():
                        if count[d] < cnt:
                            valid = False
                            break
                    if valid:
                        num = h * 100 + t * 10 + u
                        distinct.add(num)

        return len(distinct)
