class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        # Since the lengths of s and t are at most 30, we can try all possible substrings
        # from s and t, and check if their concatenation is a palindrome.

        # Get all substrings of s and t
        s_substrings = set()
        for i in range(len(s)):
            for j in range(i + 1, len(s) + 1):
                s_substrings.add(s[i:j])

        t_substrings = set()
        for i in range(len(t)):
            for j in range(i + 1, len(t) + 1):
                t_substrings.add(t[i:j])

        # Also include empty string
        s_substrings.add("")
        t_substrings.add("")

        ans = 0
        # For each substring from s and each substring from t, check if concatenation is palindrome
        for sub_s in s_substrings:
            for sub_t in t_substrings:
                candidate = sub_s + sub_t
                if candidate == candidate[::-1]:
                    ans = max(ans, len(candidate))

        return ans
