class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        # Check all substrings of length k
        for i in range(len(s) - k + 1):
            # Check if substring s[i:i+k] has all same characters
            if len(set(s[i:i+k])) == 1:
                # Check boundary conditions
                # If there is a character before, it must be different
                if i > 0 and s[i-1] == s[i]:
                    continue
                # If there is a character after, it must be different
                if i + k < len(s) and s[i+k] == s[i]:
                    continue
                return True
        return False
